// Маппинг OWM → bitmap 96x96
// Приоритет: weather.id (точный) → icon code (fallback)
inline const unsigned char* getWeatherIcon96(int weatherId, const String& owmIcon) {
    bool night = owmIcon.endsWith("n");

    switch (weatherId) {
        case 200: case 210: case 230: case 231:
            return night ? icon96_nt_chancetstorms : icon96_chancetstorms;
        case 302: case 312: case 313: case 314: case 521: case 522: case 531:
            return night ? icon96_nt_rain : icon96_rain;
        case 500:
            return night ? icon96_nt_chancerain : icon96_chancerain;
        case 511: case 612: case 615:
            return night ? icon96_nt_chancesleet : icon96_chancesleet;
        case 600:
            return night ? icon96_nt_chancesnow : icon96_chancesnow;
        case 611: case 613: case 616:
            return night ? icon96_nt_sleet : icon96_sleet;
        case 620:
            return night ? icon96_nt_chanceflurries : icon96_chanceflurries;
        case 621:
            return night ? icon96_nt_flurries : icon96_flurries;
        case 711: case 721: case 731: case 751: case 761: case 762:
            return night ? icon96_nt_hazy : icon96_hazy;
        case 771: case 781:
            return night ? icon96_nt_tstorms : icon96_tstorms;
        case 803:
            return night ? icon96_nt_mostlycloudy : icon96_mostlycloudy;
    }

    // Fallback по OWM icon code
    if (owmIcon == "01d") return icon96_sunny;
    if (owmIcon == "01n") return icon96_nt_clear;
    if (owmIcon == "02d") return icon96_mostlysunny;
    if (owmIcon == "02n") return icon96_nt_partlycloudy;
    if (owmIcon == "03d") return icon96_mostlycloudy;
    if (owmIcon == "03n") return icon96_nt_mostlycloudy;
    if (owmIcon == "04d") return icon96_cloudy;
    if (owmIcon == "04n") return icon96_nt_cloudy;
    if (owmIcon == "09d") return icon96_chancerain;
    if (owmIcon == "09n") return icon96_nt_chancerain;
    if (owmIcon == "10d") return icon96_rain;
    if (owmIcon == "10n") return icon96_nt_rain;
    if (owmIcon == "11d") return icon96_tstorms;
    if (owmIcon == "11n") return icon96_nt_tstorms;
    if (owmIcon == "13d") return icon96_snow;
    if (owmIcon == "13n") return icon96_nt_snow;
    if (owmIcon == "50d") return icon96_fog;
    if (owmIcon == "50n") return icon96_nt_fog;
    return icon96_cloudy; // fallback
}

// Маппинг OWM → bitmap 64x64
