    if (owmIcon == "02n") return icon64_nt_partlycloudy;
    if (owmIcon == "03d") return icon64_mostlycloudy;
    if (owmIcon == "03n") return icon64_nt_mostlycloudy;
    if (owmIcon == "04d") return icon64_cloudy;
    if (owmIcon == "04n") return icon64_nt_cloudy;
    if (owmIcon == "09d") return icon64_chancerain;
    if (owmIcon == "09n") return icon64_nt_chancerain;
